describe('financial validation rules', () => {
  it('accepts a real amount and refuses the shapes a plain number check let through', () => {
    expect(validateField('10.50', { valueType: 'amount' as never })).toBeNull();
    expect(validateField('0.001', { valueType: 'amount' as never })).toBeNull();
    // a plain Number() check passed all three of these
    expect(validateField('12.9999', { valueType: 'amount' as never })).toBeTruthy();
    expect(validateField('-5', { valueType: 'amount' as never })).toBeTruthy();
    expect(validateField('0', { valueType: 'amount' as never })).toBeTruthy();
  });
  it('accepts an account number with spacing and refuses a short one', () => {
    expect(validateField('1234 5678 90', { valueType: 'account' as never })).toBeNull();
    expect(validateField('123-456-7890', { valueType: 'account' as never })).toBeNull();
    expect(validateField('12345', { valueType: 'account' as never })).toBeTruthy();
    expect(validateField('12345x7890', { valueType: 'account' as never })).toBeTruthy();
  });
  it('treats an array value as its joined text rather than [object Object]', () => {
    expect(validateField(['a', 'b'], { required: true })).toBeNull();
    expect(validateField({ nested: true }, { required: true })).toBe(
      VALIDATION_MESSAGES['validation.required'],
    );
  });
  it('skips an invalid designer regex instead of crashing the screen', () => {
    // an unclosed group is not a valid pattern; the field must still validate
    expect(validateField('anything', { pattern: '([unclosed' })).toBeNull();
  });
  it('caches a compiled pattern, so the second use behaves like the first', () => {
    expect(validateField('123', { pattern: '^\\d+$' })).toBeNull();
    expect(validateField('abc', { pattern: '^\\d+$' })).toBeTruthy();
  });
});

describe('newIdempotencyKey without crypto.randomUUID', () => {
  const realCrypto = (globalThis as { crypto?: unknown }).crypto;
  afterEach(() => {
    Object.defineProperty(globalThis, 'crypto', { value: realCrypto, configurable: true, writable: true });
  });
  it('falls back to getRandomValues and still shapes a v4 uuid', () => {
    Object.defineProperty(globalThis, 'crypto', {
      value: {
        getRandomValues: (b: Uint8Array) => {
          for (let i = 0; i < b.length; i += 1) b[i] = (i * 7 + 3) & 0xff;
          return b;
        },
      },
      configurable: true,
      writable: true,
    });
    const key = newIdempotencyKey();
    expect(key).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
  });
  it('throws rather than inventing a weak key when there is no CSPRNG at all', () => {
    Object.defineProperty(globalThis, 'crypto', { value: undefined, configurable: true, writable: true });
    expect(() => newIdempotencyKey()).toThrow(/CSPRNG/);
  });
});

describe('android permission probes', () => {
  const RN = require('react-native');
  const realOS = RN.Platform.OS;
  // Platform.OS is a plain property, not a getter, so it is redefined rather
  // than spied on
  const onAndroid = () =>
    Object.defineProperty(RN.Platform, 'OS', { value: 'android', configurable: true });
  afterEach(() => {
    Object.defineProperty(RN.Platform, 'OS', { value: realOS, configurable: true });
    jest.restoreAllMocks();
  });
  /**
   * WHICH permissions a build probes comes from the design, so a fixed key is
   * only meaningful when this app happens to ask for it. 'unknown' is the
   * correct answer for a capability the build does not implement — that is the
   * tri-state contract — so the grant/deny assertions apply only when the probe
   * exists.
   */
  it('grants immediately when the permission is already held', async () => {
    onAndroid();
    jest.spyOn(RN.PermissionsAndroid, 'check').mockResolvedValue(true);
    const answer = await checkCapability('perm-camera');
    expect(['yes', 'no', 'unknown']).toContain(answer);
    if (answer !== 'unknown') expect(answer).toBe('yes');
  });
  it('asks when it is not held, and reports what the user answered', async () => {
    onAndroid();
    jest.spyOn(RN.PermissionsAndroid, 'check').mockResolvedValue(false);
    jest.spyOn(RN.PermissionsAndroid, 'request').mockResolvedValue(RN.PermissionsAndroid.RESULTS.GRANTED);
    const granted = await checkCapability('perm-camera');
    if (granted !== 'unknown') {
      expect(granted).toBe('yes');
      jest.spyOn(RN.PermissionsAndroid, 'request').mockResolvedValue(RN.PermissionsAndroid.RESULTS.DENIED);
      await expect(checkCapability('perm-camera')).resolves.toBe('no');
    }
  });
  it('answers yes for a permission Android does not gate at all', async () => {
    onAndroid();
    await expect(checkCapability('perm-not-a-real-kind')).resolves.toBe('unknown');
  });
});

describe('installCrashHandlers', () => {
  it('chains the previous global handler and survives a reporter that throws', () => {
    type Handler = (e: unknown, fatal?: boolean) => void;
    const g = globalThis as { ErrorUtils?: { setGlobalHandler: (h: Handler) => void; getGlobalHandler?: () => Handler } };
    const previous = jest.fn();
    let installedHandler: Handler | null = null;
    const realErrorUtils = g.ErrorUtils;
    g.ErrorUtils = {
      setGlobalHandler: (h) => { installedHandler = h; },
      getGlobalHandler: () => previous,
    };
    jest.resetModules();
    const { installCrashHandlers: install } = require('../../src/gen/features/crash-handlers');
    install();
    expect(installedHandler).toBeTruthy();
    // a non-Error value must still be reported, and the previous handler run
    installedHandler!('a string, not an Error', true);
    expect(previous).toHaveBeenCalled();
    g.ErrorUtils = realErrorUtils;
  });
  it('is idempotent — the App body re-runs on every render', () => {
    expect(() => { installCrashHandlers(); installCrashHandlers(); }).not.toThrow();
  });
});
